package org.wishyclip.app.ui.design

import androidx.annotation.DrawableRes
import org.wishyclip.app.R

/**
 * Every icon is a local Material Symbols Rounded vector drawable generated by `tools/gen-symbols.mjs`
 * (Apache-2.0, see ATTRIBUTIONS.md). Each has an outlined form (`ic_x`) and a filled form
 * (`ic_x_filled`); use [selected] to swap to the filled form for active states.
 */
object WishyIcons {
    /** The filled variant of [res] for selected / active states (or [res] itself if it has none). */
    fun selected(@DrawableRes res: Int): Int = SelectedIcons.of(res)

    @get:DrawableRes val Pen: Int get() = R.drawable.ic_pen
    @get:DrawableRes val Pencil: Int get() = R.drawable.ic_pencil
